WITH flattened_attrs AS (SELECT id, plan, tier_limits, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers WHERE plan = 'starter') SELECT plan, CASE WHEN entry_price >= 28 THEN 'PREMIUM' ELSE 'STANDARD' END AS entry_price_tier, CASE WHEN lowest_price >= 26 THEN 'LARGE' ELSE 'SMALL' END AS lowest_price_tier, SIZE(COLLECT_SET(plan)) AS num_plans, COUNT(*) FILTER (WHERE plan = 'starter') AS starter_rows, COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) AS enterprise_count, COUNT(*) AS event_count, COUNT(DISTINCT plan) AS distinct_plans, SUM(CASE WHEN plan = 'enterprise' THEN avg_tier_price ELSE 0 END) AS enterprise_avg_tier_price FROM flattened_attrs GROUP BY plan, CASE WHEN entry_price >= 28 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN lowest_price >= 26 THEN 'LARGE' ELSE 'SMALL' END;
